using System.Collections.Frozen;
using System.Text.Json;

namespace CaseIntake.VeteranHistory.Mock;

/// <summary>
/// The deterministic synthetic service-history dataset, loaded once from the embedded <c>service-history.json</c>
/// (generated by <c>ServiceHistoryDatasetGenerator</c> in the test project and guarded there by a drift test). Every SSN
/// is one of the Lookup mock's synthetic veterans (area 900-999, never issued). Kept separate from the Lookup mock's
/// <c>VeteranDataset</c>, so neither mock references the other.
/// </summary>
public sealed class ServiceHistoryDataset
{
    public const string ResourceName = "CaseIntake.VeteranHistory.Mock.service-history.json";

    /// <summary>The deterministic outage (plan 0.4): always answered with 503, whatever the dataset holds.</summary>
    public const string OutageSsn = "962-91-6025";

    private readonly FrozenDictionary<string, ServiceHistoryRecord> _bySsn;

    public ServiceHistoryDataset(IEnumerable<ServiceHistoryRecord> records)
    {
        ArgumentNullException.ThrowIfNull(records);
        Records = [.. records];
        _bySsn = Records.ToFrozenDictionary(r => r.Ssn, StringComparer.Ordinal);
    }

    public IReadOnlyList<ServiceHistoryRecord> Records { get; }

    public static ServiceHistoryDataset LoadEmbedded()
    {
        using var stream = typeof(ServiceHistoryDataset).Assembly.GetManifestResourceStream(ResourceName)
            ?? throw new InvalidOperationException($"Embedded resource {ResourceName} is missing.");
        var records = JsonSerializer.Deserialize(stream, HistoryMockJsonContext.Default.ServiceHistoryRecordArray)
            ?? throw new InvalidOperationException("The service-history dataset is empty.");
        return new ServiceHistoryDataset(records);
    }

    /// <summary>The dashed form (<c>NNN-NN-NNNN</c>) of a nine-digit SSN; any other value unchanged.</summary>
    public static string Dashed(string ssn)
    {
        ArgumentNullException.ThrowIfNull(ssn);
        return ssn.Length == 9 && ssn.All(char.IsAsciiDigit) ? $"{ssn[..3]}-{ssn[3..5]}-{ssn[5..]}" : ssn;
    }

    /// <summary>Finds a service history by SSN in either the dashed (<c>NNN-NN-NNNN</c>) or the nine-digit form.</summary>
    public bool TryFind(string ssn, out ServiceHistoryRecord record) => _bySsn.TryGetValue(Dashed(ssn), out record!);
}
